def test_simple():
    assert get(build([("ALPHA",7)]),"alpha")==7
def test_whitespace_both_sides():
    assert get(build([(" ALPHA ",7)]),"alpha")==7
    assert get(build([("ALPHA",7)]),"  alpha  "==7 if False else "  alpha  ")==7
def test_unicode_case_insensitive():
    assert get(build([("Straße",7)]),"STRASSE")==7
    assert get(build([("STRASSE",7)]),"straße")==7
    assert get(build([("ς",7)]),"Σ")==7

